// Generated by ChatGPT
// This file's purpose for grabbing data from USDA

import Foundation

final class USDAFoodService {
    
    // Temporary key for testing
    // WILL ADD ACTUAL API LATER
    private let apiKey = Secrets.usdaAPIKey
    
    // USDA Food Search endpoint
    private let searchURL = "https://api.nal.usda.gov/fdc/v1/foods/search"
    
    // USDA endpoint for one specific food
    private let foodDetailsURL = "https://api.nal.usda.gov/fdc/v1/food"
    
    // Function that will search USDA foods matching what the user types
    func searchFoods(query: String) async throws -> [USDAFood] {
        
        // Remove extra spaces on the beginning and/or the end of what the user types
        let cleanedQuery = query.trimmingCharacters(in: .whitespacesAndNewlines)
        
        // An empty search will not make an API request
        guard !cleanedQuery.isEmpty else {
            return []
        }
        
        // Break URL into pieces to handle characters that need URL encoding
        guard var urlComponents = URLComponents(string: searchURL) else {
            throw URLError(.badURL)
        }
        
        // Add API key and food search text
        urlComponents.queryItems = [
            URLQueryItem(name: "api_key", value: apiKey),
            URLQueryItem(name: "query", value: cleanedQuery)
        ]
        
        // Now turn those pieces (urlComponents) into a complete URL
        guard let url = urlComponents.url else {
            throw URLError(.badURL)
        }
        
        // This will send the request
        let (data, response) = try await URLSession.shared.data(from: url)
        
        // USDA will send a successful HTTP status code
        guard let httpResponse = response as? HTTPURLResponse,
              (200...299).contains(httpResponse.statusCode) else {
            throw URLError(.badServerResponse)
        }
        
        // Convert USDA JSON into the Swift Models
        let decodedResponse = try JSONDecoder().decode(USDAFoodSearchResponse.self, from: data)
        
        // Return the list of foods
        return decodedResponse.foods
        
    }
    
    // Gets the full USDA record for one selected food
    func fetchFoodDetails(
        fdcId: Int
    ) async throws -> USDAFoodDetail {
        
        // Add the selected food's FDC ID to the endpoint
        guard var urlComponents = URLComponents(
            string: "\(foodDetailsURL)/\(fdcId)"
        ) else {
            throw URLError(.badURL)
        }
        
        
        // Add our USDA API key
        urlComponents.queryItems = [
            URLQueryItem(
                name: "api_key",
                value: apiKey
            )
        ]
        
        
        // Create the final URL
        guard let url = urlComponents.url else {
            throw URLError(.badURL)
        }
        
        
        // Send request to USDA
        let (data, response) =
            try await URLSession.shared.data(from: url)
        
        
        // Make sure USDA returned a successful HTTP code
        guard let httpResponse =
                response as? HTTPURLResponse,
              (200...299).contains(
                httpResponse.statusCode
              ) else {
            
            throw URLError(.badServerResponse)
        }
        
        
        // Convert USDA JSON into USDAFoodDetail
        let foodDetails =
            try JSONDecoder().decode(
                USDAFoodDetail.self,
                from: data
            )
        
        
        return foodDetails
    }
}

